import { documentsClient } from "@dynatrace-sdk/client-document";

export default async function (payload: unknown) {
  //const filter = "type = 'dashboard' and (name starts-with 'grupo2')";
  const pageSize = 1000; // máximo permitido por la API

  let allDocuments: any[] = [];
  let pageKey: string | undefined = undefined;

  do {
    const res = await documentsClient.listDocuments({
      pageSize,
      //filter,
      adminAccess: true,
      ...(pageKey ? { pageKey } : {}), // en la primera llamada no se envía pageKey
    });

    allDocuments = allDocuments.concat(res.documents);
    pageKey = res.nextPageKey;
  } while (pageKey);

  return allDocuments;
}

import { execution } from '@dynatrace-sdk/automation-utils';

export default async function () {
  const ex = await execution();

  // Traer el resultado de la tarea anterior por su nombre
  const dashboards = await ex.result('get_dashboards');

  // Convertir el array a formato JSONL (un objeto JSON por línea)
  const jsonl = dashboards
    .map((doc) => JSON.stringify(doc))
    .join('\n');

  const request = {
    lookupField: 'id', // campo único que identifica cada registro
    filePath: '/lookups/documents_report',
    overwrite: true,
    displayName: 'documents_report',
    skippedRecords: 0,
    autoFlatten: true,
    timezone: 'UTC',
    locale: 'en_US',
    description: 'lookup table con el listado de canales digitales',
    parsePattern: 'JSON:data',
  };

  const blob = new Blob([jsonl], { type: 'application/jsonl' });
  const file = new File([blob], 'documents_report.jsonl', {
    type: 'application/jsonl',
  });

  const formData = new FormData();
  formData.append('request', JSON.stringify(request));
  formData.append('content', file);

  const response = await fetch(
    '/platform/storage/resource-store/v1/files/tabular/lookup:upload',
    {
      method: 'POST',
      body: formData,
    }
  );

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`HTTP error! status: ${response.status} - ${errorText}`);
  }

  const result = await response.json();
  console.log('Lookup data uploaded successfully:', result);

  return {
    success: true,
    totalRecords: dashboards.length,
    uploadResult: result,
  };
}
